package incapsula

import (
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"fmt"
	"net/http"
	"regexp"
	"slices"
	"sync"
	"testing"

	cryptorand "crypto/rand"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/resource"
	"github.com/hashicorp/terraform-plugin-sdk/v2/terraform"
)

// Tests for incapsula_abp_credential. The secret is generated by the service
// and can never be read back in another form, so the resource has two
// invariants worth locking down: the secret in state is the live one, and
// nothing short of a deliberate replacement may rotate it.

const abpCredentialTestAddress = "incapsula_abp_credential.test"

func abpCredentialConfig(t *testing.T, accountId string, keyIndex int) string {
	t.Helper()
	return abpCredentialConfigWithKey(accountId, abpTestRsaPublicPem(t, keyIndex))
}

func abpCredentialConfigWithKey(accountId, pem string) string {
	return fmt.Sprintf(`
resource "incapsula_abp_credential" "test" {
  account_id = %q
  rsa_key    = <<-EOT
%s
  EOT
}
`, accountId, pem)
}

// abpCredentialSmallRsaPem is a key below the 3072-bit minimum the provider
// insists on.
var abpCredentialSmallRsaPem = sync.OnceValue(func() string {
	key, err := rsa.GenerateKey(cryptorand.Reader, 2048)
	if err != nil {
		panic(err)
	}
	der, err := x509.MarshalPKIXPublicKey(&key.PublicKey)
	if err != nil {
		panic(err)
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der}))
})

// --- create -----------------------------------------------------------------

// The secret the service generated is in state only as `encrypted_secret`, and
// it decrypts to what the service holds.
func TestAbpCredential_Create(t *testing.T) {
	f := newAbpFake(t)
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config: config,
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr(abpCredentialTestAddress, "account_id", abpFakeAccountId),
					resource.TestCheckResourceAttrSet(abpCredentialTestAddress, "created_at"),
					// The service does not track modifications of a credential.
					resource.TestCheckResourceAttr(abpCredentialTestAddress, "modified_at", ""),
					func(s *terraform.State) error {
						attrs := abpAttrs(t, s, abpCredentialTestAddress)
						stored := f.only(t, abpFakeCredentials)
						secret := abpFakeString(stored["secret"])
						if got := abpDecryptSecret(t, 0, attrs["encrypted_secret"]); got != secret {
							return fmt.Errorf("encrypted_secret holds %q, want the live secret %q", got, secret)
						}
						for name, value := range attrs {
							if value == secret {
								return fmt.Errorf("the plaintext secret reached state as %s", name)
							}
						}
						return nil
					},
				),
			},
			{Config: config, PlanOnly: true},
		},
	})
}

// RSA-OAEP is randomised, so re-encrypting would produce a different
// ciphertext every time. `encrypted_secret` must therefore survive a refresh
// untouched, or the resource would never stop planning a change.
func TestAbpCredential_EncryptedSecretIsStableAcrossRefresh(t *testing.T) {
	f := newAbpFake(t)
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	var encrypted string
	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config: config,
				Check: func(s *terraform.State) error {
					encrypted = abpAttrs(t, s, abpCredentialTestAddress)["encrypted_secret"]
					return nil
				},
			},
			{Config: config, PlanOnly: true},
			{
				RefreshState: true,
				Check: func(s *terraform.State) error {
					if got := abpAttrs(t, s, abpCredentialTestAddress)["encrypted_secret"]; got != encrypted {
						return fmt.Errorf("encrypted_secret changed on refresh")
					}
					return nil
				},
			},
		},
	})
}

// --- update -----------------------------------------------------------------

// `rsa_key` only decides which key the secret in state is encrypted to, so
// changing it re-encrypts the same secret in place. The credential has no
// update endpoint at all, so any write reaching it would rotate the secret.
func TestAbpCredential_RsaKeyChangeIsInPlace(t *testing.T) {
	f := newAbpFake(t)
	var created, secret string

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config: abpCredentialConfig(t, abpFakeAccountId, 0),
				Check: func(s *terraform.State) error {
					attrs := abpAttrs(t, s, abpCredentialTestAddress)
					created = attrs["id"]
					secret = abpDecryptSecret(t, 0, attrs["encrypted_secret"])
					return nil
				},
			},
			{
				Config: abpCredentialConfig(t, abpFakeAccountId, 1),
				Check: func(s *terraform.State) error {
					attrs := abpAttrs(t, s, abpCredentialTestAddress)
					if attrs["id"] != created {
						return fmt.Errorf("changing rsa_key replaced credential %s with %s", created, attrs["id"])
					}
					if deleted := f.deletedIds(); len(deleted) != 0 {
						return fmt.Errorf("changing rsa_key deleted %v", deleted)
					}
					if got := abpDecryptSecret(t, 1, attrs["encrypted_secret"]); got != secret {
						return fmt.Errorf("the secret changed from %q to %q", secret, got)
					}
					// One POST to create it, and nothing else.
					if got := abpDomainWritesTo(f, "credential"); !slices.Equal(got, []string{http.MethodPost}) {
						return fmt.Errorf("the credential endpoints saw %v, want a single POST", got)
					}
					return nil
				},
			},
			{Config: abpCredentialConfig(t, abpFakeAccountId, 1), PlanOnly: true},
		},
	})
}

// --- replacement ------------------------------------------------------------

// A credential cannot be moved to another Account, so changing `account_id`
// replaces it — which is the only way to rotate the secret.
func TestAbpCredential_AccountIdChangeReplaces(t *testing.T) {
	f := newAbpFake(t)
	var created, secret string

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config: abpCredentialConfig(t, abpFakeAccountId, 0),
				Check: func(s *terraform.State) error {
					attrs := abpAttrs(t, s, abpCredentialTestAddress)
					created = attrs["id"]
					secret = abpDecryptSecret(t, 0, attrs["encrypted_secret"])
					return nil
				},
			},
			{
				Config: abpCredentialConfig(t, abpFakeOtherAccountId, 0),
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr(abpCredentialTestAddress, "account_id", abpFakeOtherAccountId),
					func(s *terraform.State) error {
						attrs := abpAttrs(t, s, abpCredentialTestAddress)
						if attrs["id"] == created {
							return fmt.Errorf("changing account_id did not replace credential %s", created)
						}
						if deleted := f.deletedIds(); !slices.Equal(deleted, []string{created}) {
							return fmt.Errorf("the replacement deleted %v, want just %s", deleted, created)
						}
						if got := abpDecryptSecret(t, 0, attrs["encrypted_secret"]); got == secret {
							return fmt.Errorf("the replacement kept the old secret")
						}
						return nil
					},
				),
			},
		},
	})
}

// --- drift and delete -------------------------------------------------------

// A credential deleted outside Terraform is recreated, with a new secret.
func TestAbpCredential_DeletedOutOfBandIsRecreated(t *testing.T) {
	f := newAbpFake(t)
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	var created string
	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config: config,
				Check: func(s *terraform.State) error {
					created = abpAttrs(t, s, abpCredentialTestAddress)["id"]
					return nil
				},
			},
			{
				PreConfig: func() { f.drop(abpFakeCredentials, created) },
				Config:    config,
				Check: func(s *terraform.State) error {
					attrs := abpAttrs(t, s, abpCredentialTestAddress)
					if attrs["id"] == created {
						return fmt.Errorf("the vanished credential %s was not recreated", created)
					}
					stored := f.only(t, abpFakeCredentials)
					if got := abpDecryptSecret(t, 0, attrs["encrypted_secret"]); got != abpFakeString(stored["secret"]) {
						return fmt.Errorf("encrypted_secret does not hold the new credential's secret")
					}
					return nil
				},
			},
			{Config: config, PlanOnly: true},
		},
	})
}

// The secret itself cannot drift: the service generates it once and has no way
// to change it. A credential whose secret is rewritten out of band is adopted
// silently, because `encrypted_secret` is not re-derived by a read — the
// plaintext would have to be in state for that to be possible.
func TestAbpCredential_SecretDriftIsNotDetected(t *testing.T) {
	f := newAbpFake(t)
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	var encrypted string
	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config: config,
				Check: func(s *terraform.State) error {
					attrs := abpAttrs(t, s, abpCredentialTestAddress)
					encrypted = attrs["encrypted_secret"]
					f.mutate(t, abpFakeCredentials, attrs["id"], func(doc map[string]any) {
						doc["secret"] = "rotated-elsewhere"
					})
					return nil
				},
			},
			{Config: config, PlanOnly: true},
			{
				Config: config,
				Check: func(s *terraform.State) error {
					if got := abpAttrs(t, s, abpCredentialTestAddress)["encrypted_secret"]; got != encrypted {
						return fmt.Errorf("encrypted_secret was expected to still hold the stale secret")
					}
					return nil
				},
			},
		},
	})
}

func TestAbpCredential_Destroy(t *testing.T) {
	f := newAbpFake(t)

	var created string
	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		CheckDestroy: func(s *terraform.State) error {
			if f.exists(abpFakeCredentials, created) {
				return fmt.Errorf("credential %s survived the destroy", created)
			}
			if deleted := f.deletedIds(); !slices.Equal(deleted, []string{created}) {
				return fmt.Errorf("the destroy deleted %v, want just %s", deleted, created)
			}
			return nil
		},
		Steps: []resource.TestStep{
			{
				Config: abpCredentialConfig(t, abpFakeAccountId, 0),
				Check: func(s *terraform.State) error {
					created = abpAttrs(t, s, abpCredentialTestAddress)["id"]
					return nil
				},
			},
		},
	})
}

// --- import -----------------------------------------------------------------

// `rsa_key` is not part of the remote object and `encrypted_secret` is derived
// from it, so neither can be imported.
func TestAbpCredential_Import(t *testing.T) {
	f := newAbpFake(t)
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{Config: config},
			{
				Config:                  config,
				ResourceName:            abpCredentialTestAddress,
				ImportState:             true,
				ImportStateVerify:       true,
				ImportStateVerifyIgnore: []string{"rsa_key", "encrypted_secret"},
			},
		},
	})
}

// The first apply after an import must keep the imported credential — a
// replacement would delete the live secret the analysis host authenticates
// with — and must fill `encrypted_secret` in place.
func TestAbpCredential_ImportThenApplyKeepsCredential(t *testing.T) {
	f := newAbpFake(t)
	seeded := f.seedCredential()
	seededId := abpFakeString(seeded["id"])
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config:             config,
				ResourceName:       abpCredentialTestAddress,
				ImportState:        true,
				ImportStateId:      seededId,
				ImportStatePersist: true,
			},
			{
				Config: config,
				Check: func(s *terraform.State) error {
					attrs := abpAttrs(t, s, abpCredentialTestAddress)
					if attrs["id"] != seededId {
						return fmt.Errorf("the imported credential %s was replaced by %s", seededId, attrs["id"])
					}
					if !f.exists(abpFakeCredentials, seededId) {
						return fmt.Errorf("the imported credential %s was deleted", seededId)
					}
					if deleted := f.deletedIds(); len(deleted) != 0 {
						return fmt.Errorf("the first apply after import deleted %v", deleted)
					}
					want := abpFakeString(seeded["secret"])
					if got := abpDecryptSecret(t, 0, attrs["encrypted_secret"]); got != want {
						return fmt.Errorf("encrypted_secret holds %q, want the live secret %q", got, want)
					}
					return nil
				},
			},
			{Config: config, PlanOnly: true},
		},
	})
}

func TestAbpCredential_ImportErrors(t *testing.T) {
	f := newAbpFake(t)
	config := abpCredentialConfig(t, abpFakeAccountId, 0)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{Config: config},
			{
				Config:        config,
				ResourceName:  abpCredentialTestAddress,
				ImportState:   true,
				ImportStateId: abpFakeAbsentId,
				ExpectError:   regexp.MustCompile(`ABP Credential ` + abpFakeAbsentId + ` not found`),
			},
			{
				Config:        config,
				ResourceName:  abpCredentialTestAddress,
				ImportState:   true,
				ImportStateId: " ",
				ExpectError:   regexp.MustCompile(`expected import ID to be '<credential_id>'`),
			},
		},
	})
}

// --- validation -------------------------------------------------------------

func TestAbpCredential_InvalidAccountIdIsRejectedAtPlanTime(t *testing.T) {
	f := newAbpFake(t)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config:      abpCredentialConfig(t, "not-a-uuid", 0),
				PlanOnly:    true,
				ExpectError: regexp.MustCompile(`expected "account_id" to be a valid UUID`),
			},
		},
	})
}

// Known limitation: `rsa_key` is not validated at plan time, so a key the
// provider cannot encrypt to is only rejected after the credential has been
// created. The apply fails with an orphaned credential already on the server.
func TestAbpCredential_BadRsaKeyFailsAfterTheCredentialIsCreated(t *testing.T) {
	f := newAbpFake(t)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config:      abpCredentialConfigWithKey(abpFakeAccountId, "not a PEM block at all"),
				ExpectError: regexp.MustCompile(`error decoding RSA PEM no entities found`),
			},
		},
	})

	if got := f.requestCount(http.MethodPost, "/credential"); got != 1 {
		t.Fatalf("the failed apply sent %d credential creates, want 1", got)
	}
}

// Known limitation: the key size check also runs after the create, for the same
// reason.
func TestAbpCredential_SmallRsaKeyFailsAfterTheCredentialIsCreated(t *testing.T) {
	f := newAbpFake(t)

	resource.Test(t, resource.TestCase{
		ProviderFactories: f.providers(t),
		Steps: []resource.TestStep{
			{
				Config:      abpCredentialConfigWithKey(abpFakeAccountId, abpCredentialSmallRsaPem()),
				ExpectError: regexp.MustCompile(`RSA key size must be at least 3072 bits, got 2048 bits`),
			},
		},
	})

	if got := f.requestCount(http.MethodPost, "/credential"); got != 1 {
		t.Fatalf("the failed apply sent %d credential creates, want 1", got)
	}
}
